-- =====================================================================
-- 081 — drug_profiles: lote 2 de conteúdo (indicações, efeitos, precauções)
-- ---------------------------------------------------------------------
-- Alarga o método da migração 080 a mais 12 fármacos já existentes na BD
-- (digoxina, amiodarona, ciprofloxacina, metronidazol, carbamazepina,
-- fenitoina, valproato, metformina, levotiroxina, atorvastatina,
-- amlodipina, omeprazol) e completa a furosemida (perfil criado na 079
-- mas sem indicações/efeitos/precauções).
-- Fontes: rótulos aprovados pela FDA (DailyMed/NIH/NLM — secções
-- INDICATIONS AND USAGE, ADVERSE REACTIONS, CONTRAINDICATIONS e
-- WARNINGS AND PRECAUTIONS; omeprazol: rótulo OTC aprovado) e
-- corroborado pelo Prontuário Terapêutico do INFARMED (11.ª ed., 2012,
-- fontes_interacoes/prontuario_utf8.txt). Conteúdo autoral (não
-- copiado), em bullets separados por \n (renderizados como lista).
-- Idempotente: reaplicar é seguro (INSERT ... ON CONFLICT DO NOTHING;
-- UPDATE re-escrito com valores idênticos).
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. INSERT 12 perfis novos (fármacos já existentes em public.drugs)
-- ---------------------------------------------------------------------
INSERT INTO public.drug_profiles
  (drug_id, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
   indications_pt, indications_en, side_effects_pt, side_effects_en,
   precautions_pt, precautions_en, source_pt, source_en, status)
SELECT d.id, v.overview_public_pt, v.overview_public_en, v.overview_pro_pt, v.overview_pro_en,
       v.indications_pt, v.indications_en, v.side_effects_pt, v.side_effects_en,
       v.precautions_pt, v.precautions_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('digoxina',
   'A digoxina é um medicamento para o coração usado na insuficiência cardíaca e para controlar o ritmo cardíaco irregular (fibrilhação auricular). Fortalece o batimento do coração e abranda a condução elétrica. Tem uma margem estreita entre a dose eficaz e a tóxica, pelo que exige análises regulares.',
   'Digoxin is a heart medicine used in heart failure and to control an irregular heart rhythm (atrial fibrillation). It strengthens the heartbeat and slows electrical conduction. It has a narrow margin between the effective and the toxic dose, so regular blood tests are required.',
   'Glicósido digitálico (inibidor da Na+/K+-ATPase). Indicado na insuficiência cardíaca e no controlo da resposta ventricular na fibrilhação auricular. Índice terapêutico estreito; toxicidade agravada por hipocaliemia, hipomagnesiemia, hipercalcemia, idade avançada e insuficiência renal.',
   'Digitalis glycoside (Na+/K+-ATPase inhibitor). Indicated in heart failure and for ventricular rate control in atrial fibrillation. Narrow therapeutic index; toxicity aggravated by hypokalaemia, hypomagnesaemia, hypercalcaemia, advanced age and renal impairment.',
   E'Tratamento da insuficiência cardíaca (redução das hospitalizações por insuficiência cardíaca).\nControlo da frequência ventricular na fibrilhação auricular.',
   E'Treatment of heart failure (reduction of hospitalisations for heart failure).\nControl of ventricular rate in atrial fibrillation.',
   E'Náuseas, vómitos e falta de apetite — podem ser sinais precoces de toxicidade.\nAlterações da visão (visão desfocada, perturbação das cores).\nArritmias cardíacas — o sinal mais frequente de toxicidade.\nDor de cabeça, fraqueza, tonturas ou confusão.\nGinecomastia em uso prolongado (raro).\nProcure ajuda imediata se tiver náuseas persistentes, alterações da visão, batimento irregular ou desmaios.',
   E'Nausea, vomiting and loss of appetite — may be early signs of toxicity.\nVisual changes (blurred vision, colour disturbance).\nCardiac arrhythmias — the most frequent sign of toxicity.\nHeadache, weakness, dizziness or confusion.\nGynaecomastia with prolonged use (rare).\nSeek immediate help if you have persistent nausea, visual changes, an irregular heartbeat or fainting.',
   E'Análises regulares (nível de digoxina no sangue, potássio, magnésio e função renal).\nNunca altere a dose por sua conta.\nInforme o médico de todos os medicamentos — muitos aumentam o nível de digoxina (ex.: amiodarona, captopril, claritromicina).\nNão usar na fibrilhação auricular associada a síndrome de Wolff-Parkinson-White.\nCuidado com diuréticos que baixam o potássio — fale com o médico.',
   E'Regular blood tests (serum digoxin level, potassium, magnesium and kidney function).\nNever change the dose on your own.\nTell your doctor about all medicines — many raise the digoxin level (e.g. amiodarone, captopril, clarithromycin).\nDo not use in atrial fibrillation associated with Wolff-Parkinson-White syndrome.\nBe careful with diuretics that lower potassium — talk to your doctor.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Digoxina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e61d2108-d871-44c0-b12a-2e61fbb56967 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Digoxin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e61d2108-d871-44c0-b12a-2e61fbb56967 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('amiodarona',
   'A amiodarona é um antiarrítmico usado em arritmias graves do coração que não responderam a outros tratamentos. É muito eficaz, mas pode afetar vários órgãos (pulmão, fígado, tiroide, olhos, pele), pelo que exige vigilância médica apertada e análises/ECG regulares.',
   'Amiodarone is an antiarrhythmic used for serious heart rhythm disorders that have not responded to other treatments. It is very effective, but can affect several organs (lungs, liver, thyroid, eyes, skin), so it requires close medical monitoring and regular tests/ECGs.',
   'Antiarrítmico classe III (bloqueio dos canais de sódio, potássio e cálcio, com betabloqueio). Reservado a arritmias ventriculares potencialmente fatais ou fibrilhação auricular sintomática refratária. Meia-vida muito longa (15–142 dias); toxicidade pulmonar, hepática, tiroideia e ocular; inibidor do CYP2D6/3A4 (muitas interações).',
   'Class III antiarrhythmic (sodium, potassium and calcium channel blockade, with beta-blockade). Reserved for potentially fatal ventricular arrhythmias or refractory symptomatic atrial fibrillation. Very long half-life (15–142 days); pulmonary, hepatic, thyroid and ocular toxicity; CYP2D6/3A4 inhibitor (numerous interactions).',
   E'Tratamento de fibrilhação ventricular recorrente e taquicardia ventricular instável potencialmente fatais, documentadas, em adultos sem resposta a doses adequadas de outros antiarrítmicos (ou com intolerância a eles).',
   E'Treatment of documented, life-threatening recurrent ventricular fibrillation and recurrent haemodynamically unstable ventricular tachycardia in adults who have not responded to adequate doses of other antiarrhythmics (or cannot tolerate them).',
   E'Tosse seca, falta de ar ou dor no peito — toxicidade pulmonar (grave; avaliação imediata).\nFadiga, tremores, falta de coordenação, tonturas.\nNáuseas, vómitos, obstipação ou perda de apetite.\nAlterações da visão (halos, visão desfocada) — avisar o médico.\nFotossensibilidade (queimaduras solares fáceis) e coloração azulada/acinzentada da pele.\nAlterações da tiroide (hipo ou hipertiroidismo): fadiga, variações de peso, intolerância ao frio/calor.',
   E'Dry cough, shortness of breath or chest pain — pulmonary toxicity (serious; seek immediate evaluation).\nFatigue, tremors, lack of coordination, dizziness.\nNausea, vomiting, constipation or loss of appetite.\nVisual changes (halos, blurred vision) — tell your doctor.\nPhotosensitivity (easy sunburn) and blue-grey skin discolouration.\nThyroid changes (hypo- or hyperthyroidism): fatigue, weight changes, cold/heat intolerance.',
   E'O início exige avaliação basal (radiografia do tórax, provas de função pulmonar, tiroide e fígado) e vigilância periódica.\nOs efeitos podem persistir semanas após parar (meia-vida longa).\nEvitar exposição solar e usar protetor solar.\nInformar o médico de todos os medicamentos — muitas interações (aumenta níveis de varfarina, digoxina e estatinas).\nNão usar em choque cardiogénico, bloqueio AV de 2.º/3.º grau, bradicardia com síncope sem pacemaker ou alergia (incluindo ao iodo).',
   E'Initiation requires baseline assessment (chest X-ray, pulmonary function tests, thyroid and liver tests) and periodic monitoring.\nEffects can persist for weeks after stopping (long half-life).\nAvoid sun exposure and use sunscreen.\nTell your doctor about all medicines — many interactions (raises levels of warfarin, digoxin and statins).\nDo not use in cardiogenic shock, 2nd/3rd degree AV block, bradycardia with syncope without a pacemaker, or allergy (including to iodine).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Amiodarona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4c149392-a4f0-4e2d-a13f-2b94810005de — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Amiodarone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4c149392-a4f0-4e2d-a13f-2b94810005de — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('ciprofloxacina',
   'A ciprofloxacina é um antibiótico (fluoroquinolona) usado para tratar várias infeções bacterianas (pele, osso, intestino, próstata, entre outras). É eficaz, mas está associada a efeitos raros porém graves (tendões, nervos), pelo que deve ser usada apenas com indicação médica.',
   'Ciprofloxacin is an antibiotic (fluoroquinolone) used to treat several bacterial infections (skin, bone, intestine, prostate, among others). It is effective, but is associated with rare yet serious effects (tendons, nerves), so it should be used only on medical advice.',
   'Fluoroquinolona de largo espetro (atividade contra Gram-negativos e alguns Gram-positivos). Indicada em infeções de pele, osso, intra-abdominais, diarreia infeciosa, febre tifoide, prostatite, antraz e peste. Risco de tendinopatia/rotura tendinosa, neuropatia periférica e efeitos no SNC; prolonga o QT; contraindicada com tizanidina.',
   'Broad-spectrum fluoroquinolone (active against Gram-negatives and some Gram-positives). Indicated in skin, bone, intra-abdominal infections, infectious diarrhoea, typhoid fever, prostatitis, anthrax and plague. Risk of tendinopathy/tendon rupture, peripheral neuropathy and CNS effects; prolongs the QT interval; contraindicated with tizanidine.',
   E'Infeções da pele e tecidos moles.\nInfeções ósseas e articulares.\nInfeções intra-abdominais complicadas (em associação com metronidazol).\nDiarreia infeciosa.\nFebre tifoide (febre entérica).\nProstatite bacteriana crónica.\nAntraz por inalação (pós-exposição) e peste.',
   E'Skin and skin structure infections.\nBone and joint infections.\nComplicated intra-abdominal infections (with metronidazole).\nInfectious diarrhoea.\nTyphoid fever (enteric fever).\nChronic bacterial prostatitis.\nInhalational anthrax (post-exposure) and plague.',
   E'Náuseas, diarreia ou vómitos.\nAlterações das provas de função hepática.\nDor de cabeça, tonturas ou insónia.\nDor, inchaço ou rotura de tendões — parar e procurar ajuda imediata.\nFormigueiro, dormência ou fraqueza (neuropatia periférica) — parar e avisar o médico.\nErupção cutânea ou fotossensibilidade.\nPalpitações ou desmaios (prolongamento do QT).',
   E'Nausea, diarrhoea or vomiting.\nAbnormal liver function tests.\nHeadache, dizziness or insomnia.\nTendon pain, swelling or rupture — stop and seek immediate help.\nTingling, numbness or weakness (peripheral neuropathy) — stop and tell your doctor.\nSkin rash or photosensitivity.\nPalpitations or fainting (QT prolongation).',
   E'Parar imediatamente ao primeiro sinal de dor tendinosa, formigueiro, alterações do SNC ou reação alérgica.\nRisco aumentado de rotura tendinosa em maiores de 60 anos, com corticosteroides ou após transplante.\nEvitar em doentes com miastenia gravis.\nNão usar em doentes com antecedentes de reações graves a fluoroquinolonas.\nEvitar exposição solar durante o tratamento.\nContraindicada com tizanidina; cuidado com fármacos que prolongam o QT.\nNa gravidez e em crianças, só com avaliação médica.',
   E'Stop immediately at the first sign of tendon pain, tingling, CNS changes or an allergic reaction.\nIncreased risk of tendon rupture in patients over 60, on corticosteroids or after transplantation.\nAvoid in patients with myasthenia gravis.\nDo not use in patients with a history of serious reactions to fluoroquinolones.\nAvoid sun exposure during treatment.\nContraindicated with tizanidine; caution with QT-prolonging drugs.\nIn pregnancy and children, only on medical assessment.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ciprofloxacina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=58388197-82f4-0953-e063-6294a90ac52a — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Ciprofloxacin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=58388197-82f4-0953-e063-6294a90ac52a — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('metronidazol',
   'O metronidazol é um antibiótico usado em infeções por bactérias anaeróbias e por certos parasitas (tricomoníase, amebíase). Durante o tratamento e até 3 dias depois, não deve beber álcool — provoca uma reação desagradável (cólicas, náuseas, vómitos, rubor).',
   'Metronidazole is an antibiotic used for infections caused by anaerobic bacteria and by certain parasites (trichomoniasis, amoebiasis). During treatment and for up to 3 days after, do not drink alcohol — it causes an unpleasant reaction (cramps, nausea, vomiting, flushing).',
   'Nitroimidazol com atividade antiprotozoária e antibacteriana (anaeróbios). Indicado na tricomoníase, amebíase e infeções anaeróbias graves. Interage com o álcool (reação tipo dissulfiram) e potencia a anticoagulação da varfarina; neuropatia periférica e encefalopatia com doses elevadas ou prolongadas.',
   'Nitroimidazole with antiprotozoal and antibacterial (anaerobe) activity. Indicated in trichomoniasis, amoebiasis and serious anaerobic infections. Interacts with alcohol (disulfiram-like reaction) and potentiates warfarin anticoagulation; peripheral neuropathy and encephalopathy with high or prolonged doses.',
   E'Tricomoníase sintomática e assintomática (incluindo tratamento simultâneo de parceiros sexuais).\nAmebíase intestinal aguda (disenteria amébica) e abcesso hepático amébico.\nInfeções bacterianas anaeróbias graves: intra-abdominais, pele e tecidos moles, ginecológicas, septicemia, e osso/articulações (como adjuvante).',
   E'Symptomatic and asymptomatic trichomoniasis (including simultaneous treatment of sexual partners).\nAcute intestinal amoebiasis (amoebic dysentery) and amoebic liver abscess.\nSerious anaerobic bacterial infections: intra-abdominal, skin and skin structure, gynaecological, septicaemia, and bone/joint (as adjunctive therapy).',
   E'Gosto metálico na boca e boca seca.\nNáuseas, vómitos, diarreia ou desconforto abdominal.\nDor de cabeça ou tonturas.\nUrina mais escura.\nFormigueiro, dormência ou dor nos membros (neuropatia periférica) — parar e avisar o médico.\nConvulsões ou confusão com doses elevadas.',
   E'Metallic taste in the mouth and dry mouth.\nNausea, vomiting, diarrhoea or abdominal discomfort.\nHeadache or dizziness.\nDarker urine.\nTingling, numbness or pain in the limbs (peripheral neuropathy) — stop and tell your doctor.\nSeizures or confusion with high doses.',
   E'Não consumir álcool durante o tratamento e pelo menos 3 dias depois (reação tipo dissulfiram: cólicas, náuseas, vómitos, rubor).\nNão administrar a doentes que tomaram dissulfiram nas últimas 2 semanas.\nParar o tratamento se surgirem sinais de neuropatia periférica (formigueiro ou dormência).\nEvitar no 1.º trimestre de gravidez (tricomoníase) — falar com o médico.\nContraindicado na síndrome de Cockayne.\nCom varfarina: monitorizar o INR.',
   E'Do not drink alcohol during treatment and for at least 3 days after (disulfiram-like reaction: cramps, nausea, vomiting, flushing).\nDo not give to patients who have taken disulfiram within the last 2 weeks.\nStop treatment if signs of peripheral neuropathy appear (tingling or numbness).\nAvoid in the first trimester of pregnancy (trichomoniasis) — talk to your doctor.\nContraindicated in Cockayne syndrome.\nWith warfarin: monitor the INR.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Metronidazol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5cc3fd98-d579-432e-a4b5-b6d5586991a6 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Metronidazole label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5cc3fd98-d579-432e-a4b5-b6d5586991a6 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('carbamazepina',
   'A carbamazepina é um medicamento usado para controlar crises epiléticas (convulsões) e para aliviar a dor da neuralgia do trigémeo. Pode causar sonolência e tonturas no início, e exige análises regulares (sangue, fígado, sódio).',
   'Carbamazepine is a medicine used to control epileptic seizures (convulsions) and to relieve the pain of trigeminal neuralgia. It can cause drowsiness and dizziness at first, and requires regular blood tests (blood counts, liver, sodium).',
   'Anticonvulsivante (bloqueio dos canais de sódio dependentes de voltagem); analgésico específico na neuralgia do trigémeo. Indutor enzimático potente (CYP3A4/2C9) — múltiplas interações. Risco raro mas grave de anemia aplástica/agranulocitose e de reações cutâneas graves (SJS/TEN, associadas ao HLA-B*1502 em populações asiáticas).',
   'Anticonvulsant (voltage-gated sodium channel blockade); specific analgesic in trigeminal neuralgia. Potent enzyme inducer (CYP3A4/2C9) — numerous interactions. Rare but serious risk of aplastic anaemia/agranulocytosis and of severe skin reactions (SJS/TEN, associated with HLA-B*1502 in Asian populations).',
   E'Epilepsia: crises parciais (psicomotoras) e crises tónico-clónicas generalizadas (grand mal).\nNeuralgia do trigémeo.',
   E'Epilepsy: partial (psychomotor) seizures and generalised tonic-clonic (grand mal) seizures.\nTrigeminal neuralgia.',
   E'Tonturas, sonolência, falta de equilíbrio — frequentes no início.\nNáuseas ou vómitos.\nVisão dupla ou desfocada, dor de cabeça, fadiga.\nErupção cutânea — pode ser grave (SJS/TEN); parar e procurar ajuda imediata.\nFebre, infeções frequentes, cansaço ou hemorragias (anemia aplástica/agranulocitose — raras, graves).\nConfusão, dor de cabeça, náuseas (sódio baixo).',
   E'Dizziness, drowsiness, unsteadiness — common at the start.\nNausea or vomiting.\nDouble or blurred vision, headache, fatigue.\nSkin rash — can be severe (SJS/TEN); stop and seek immediate help.\nFever, frequent infections, tiredness or bleeding (aplastic anaemia/agranulocytosis — rare, serious).\nConfusion, headache, nausea (low sodium).',
   E'Não suspender bruscamente (risco de crises ou estado de mal epilético).\nAnálises regulares: hemograma, função hepática e sódio.\nInformar o médico de todos os medicamentos — reduz o efeito de contracetivos, anticoagulantes e outros (indutor enzimático).\nVigiar sinais de infeção, febre ou hemorragias.\nPopulações asiáticas: risco aumentado de reações cutâneas graves — informar o médico.',
   E'Do not stop abruptly (risk of seizures or status epilepticus).\nRegular blood tests: blood counts, liver function and sodium.\nTell your doctor about all medicines — reduces the effect of contraceptives, anticoagulants and others (enzyme inducer).\nWatch for signs of infection, fever or bleeding.\nAsian populations: increased risk of severe skin reactions — tell your doctor.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Carbamazepina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=52cf3ba9-0a7c-4809-830e-af93d1532726 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Carbamazepine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=52cf3ba9-0a7c-4809-830e-af93d1532726 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('fenitoina',
   'A fenitoína é um medicamento para controlar crises epiléticas (tónico-clónicas e parciais) e para prevenir crises após cirurgia ao cérebro. Exige análises regulares (nível no sangue) e vigilância dentária, porque pode fazer crescer as gengivas.',
   'Phenytoin is a medicine used to control epileptic seizures (tonic-clonic and partial) and to prevent seizures after brain surgery. It requires regular blood tests (blood level) and dental care, because it can make the gums grow.',
   'Hidantoína (bloqueio dos canais de sódio). Antiepilético nas crises tónico-clónicas e parciais; profilaxia de crises pós-neurocirurgia. Cinética não linear (níveis difíceis de prever); induz CYP (muitas interações); teratogénica; toxicidade dose-dependente (nistagmo, ataxia).',
   'Hydantoin (sodium channel blockade). Antiepileptic in tonic-clonic and partial seizures; prophylaxis of post-neurosurgery seizures. Non-linear kinetics (unpredictable levels); CYP inducer (numerous interactions); teratogenic; dose-dependent toxicity (nystagmus, ataxia).',
   E'Tratamento de crises tónico-clónicas (grand mal) e psicomotoras (lobo temporal).\nPrevenção e tratamento de crises durante ou após neurocirurgia.',
   E'Treatment of tonic-clonic (grand mal) and psychomotor (temporal lobe) seizures.\nPrevention and treatment of seizures during or after neurosurgery.',
   E'Nistagmo, ataxia, fala arrastada, falta de coordenação — frequentes e relacionados com a dose.\nSonolência, tonturas ou confusão.\nCrescimento das gengivas (hiperplasia gengival).\nErupção cutânea — pode ser grave; parar e procurar ajuda imediata.\nNáuseas ou vómitos.\nFebre, infeções ou hemorragias (alterações do sangue — raras, graves).',
   E'Nystagmus, ataxia, slurred speech, lack of coordination — common and dose-related.\nDrowsiness, dizziness or confusion.\nGum overgrowth (gingival hyperplasia).\nSkin rash — can be severe; stop and seek immediate help.\nNausea or vomiting.\nFever, infections or bleeding (blood disorders — rare, serious).',
   E'Não suspender bruscamente (risco de estado de mal epilético).\nAnálises regulares (nível de fenitoína, hemograma, função hepática).\nBoa higiene oral e vigilância dentária (gengivas).\nClasse dos antiepiléticos: risco de pensamentos ou comportamentos suicidas — vigiar alterações do humor.\nTeratogénica: na gravidez, usar contraceção eficaz e informar o médico.\nMuitas interações — informar sempre o médico de outros medicamentos.',
   E'Do not stop abruptly (risk of status epilepticus).\nRegular blood tests (phenytoin level, blood counts, liver function).\nGood oral hygiene and dental care (gums).\nAntiepileptic class: risk of suicidal thoughts or behaviour — watch for mood changes.\nTeratogenic: in pregnancy, use effective contraception and inform your doctor.\nNumerous interactions — always tell your doctor about other medicines.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Fenitoína: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ef4e97a7-cd18-47a9-a016-2eca5481a87e — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Phenytoin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ef4e97a7-cd18-47a9-a016-2eca5481a87e — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('valproato',
   'O valproato é um medicamento para controlar certos tipos de crises epiléticas (parciais e de ausência). É muito eficaz, mas tem riscos importantes — sobretudo para o fígado e na gravidez —, pelo que o tratamento é vigiado de perto pelo médico.',
   'Valproate is a medicine used to control certain types of epileptic seizures (partial and absence). It is very effective, but has important risks — mainly for the liver and in pregnancy — so treatment is closely monitored by the doctor.',
   'Ácido valproico — antiepilético de largo espetro (crises parciais, ausências; também perturbação bipolar e profilaxia da enxaqueca). Risco de hepatotoxicidade fatal (especialmente <2 anos, politerapia, doenças mitocondriais/POLG), pancreatite e hiperamoniemia; teratogénico (diminuição do QI, defeitos do tubo neural) — evitar na gravidez salvo falência de alternativas.',
   'Valproic acid — broad-spectrum antiepileptic (partial and absence seizures; also bipolar disorder and migraine prophylaxis). Risk of fatal hepatotoxicity (especially <2 years, polytherapy, mitochondrial/POLG disorders), pancreatitis and hyperammonaemia; teratogenic (decreased IQ, neural tube defects) — avoid in pregnancy unless alternatives have failed.',
   E'Epilepsia: crises parciais complexas (monoterapia ou adjuvante).\nCrises de ausência simples e complexas, e adjuvante em doentes com múltiplos tipos de crises que incluem ausências.\n(Também usado na perturbação bipolar e na profilaxia da enxaqueca — uso especializado.)',
   E'Epilepsy: complex partial seizures (monotherapy or adjunctive therapy).\nSimple and complex absence seizures, and adjunctively in patients with multiple seizure types that include absence seizures.\n(Also used in bipolar disorder and migraine prophylaxis — specialist use.)',
   E'Náuseas, vómitos, dor abdominal ou diarreia.\nSonolência, tremores, tonturas, visão dupla ou desfocada.\nQueda de cabelo ou aumento de peso.\nSinais de lesão hepática (raros, graves): cansaço intenso, perda de apetite, vómitos, amarelecimento da pele — procurar ajuda imediata.\nDor abdominal intensa (pancreatite) — procurar ajuda imediata.\nConfusão ou sonolência excessiva (amónia alta).',
   E'Nausea, vomiting, abdominal pain or diarrhoea.\nDrowsiness, tremors, dizziness, double or blurred vision.\nHair loss or weight gain.\nSigns of liver injury (rare, serious): severe tiredness, loss of appetite, vomiting, yellowing of the skin — seek immediate help.\nSevere abdominal pain (pancreatitis) — seek immediate help.\nConfusion or excessive drowsiness (high ammonia).',
   E'Contraindicado em doença hepática, distúrbios do ciclo da ureia e doenças mitocondriais (POLG).\nAnálises regulares (função hepática, amónia, hemograma), sobretudo nos primeiros 6 meses.\nNão usar na gravidez (risco de defeitos do tubo neural e diminuição do QI) — mulheres em idade fértil com contraceção eficaz.\nVigiar sinais de lesão hepática e de pancreatite.\nNão suspender bruscamente.',
   E'Contraindicated in liver disease, urea cycle disorders and mitochondrial (POLG) disorders.\nRegular blood tests (liver function, ammonia, blood counts), especially in the first 6 months.\nDo not use in pregnancy (risk of neural tube defects and decreased IQ) — women of childbearing potential with effective contraception.\nWatch for signs of liver injury and pancreatitis.\nDo not stop abruptly.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ácido valproico: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4b619f73-44e5-4a99-b425-a96cb2228c87 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Valproic acid label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4b619f73-44e5-4a99-b425-a96cb2228c87 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('metformina',
   'A metformina é o medicamento de primeira linha para a diabetes tipo 2. Ajuda a baixar o açúcar no sangue, muitas vezes em conjunto com dieta e exercício. É geralmente bem tolerada; os efeitos mais comuns são gastrointestinais no início do tratamento.',
   'Metformin is the first-line medicine for type 2 diabetes. It helps lower blood sugar, often together with diet and exercise. It is generally well tolerated; the most common effects are gastrointestinal at the start of treatment.',
   'Biguanida (ativa a AMPK; reduz a produção hepática de glucose e melhora a sensibilidade à insulina). Primeira linha na diabetes tipo 2; não causa hipoglicemia isoladamente. Risco raro de acidose láctica (contraindicada com TFG <30; suspender com contraste iodado); défice de vitamina B12 em uso prolongado.',
   'Biguanide (activates AMPK; reduces hepatic glucose production and improves insulin sensitivity). First-line in type 2 diabetes; does not cause hypoglycaemia on its own. Rare risk of lactic acidosis (contraindicated with eGFR <30; hold with iodinated contrast); vitamin B12 deficiency with long-term use.',
   E'Melhoria do controlo glicémico (adjuvante de dieta e exercício) em adultos e crianças com 10 ou mais anos com diabetes tipo 2.',
   E'Improvement of glycaemic control (adjunct to diet and exercise) in adults and children aged 10 years and older with type 2 diabetes.',
   E'Diarreia, náuseas ou vómitos — frequentes no início (melhoram com o tempo).\nDor abdominal, desconforto, gases ou azia.\nSabor metálico ou alterado na boca.\nDor de cabeça ou tonturas.\nSinais raros de acidose láctica (procurar ajuda imediata): cansaço intenso, fraqueza muscular, dor abdominal, dificuldade em respirar, sonolência, batimento irregular.',
   E'Diarrhoea, nausea or vomiting — common at the start (improve over time).\nAbdominal pain, discomfort, gas or heartburn.\nMetallic or altered taste in the mouth.\nHeadache or dizziness.\nRare signs of lactic acidosis (seek immediate help): severe tiredness, muscle weakness, abdominal pain, trouble breathing, drowsiness, irregular heartbeat.',
   E'Análises regulares da função renal antes e durante o tratamento.\nSuspender temporariamente antes de exames com contraste iodado (e reavaliar 48 horas depois).\nNão usar com TFG <30; não iniciar com TFG entre 30 e 45.\nVigiar sintomas de acidose láctica, sobretudo com desidratação, álcool em excesso ou insuficiência cardíaca.\nUso prolongado: vigiar vitamina B12.',
   E'Regular kidney function tests before and during treatment.\nHold temporarily before imaging with iodinated contrast (and reassess 48 hours later).\nDo not use with eGFR <30; do not start with eGFR between 30 and 45.\nWatch for symptoms of lactic acidosis, especially with dehydration, excess alcohol or heart failure.\nLong-term use: monitor vitamin B12.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Metformina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c1bfc7b5-c7e0-4353-b772-05d463c12886 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Metformin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c1bfc7b5-c7e0-4353-b772-05d463c12886 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('levotiroxina',
   'A levotiroxina é a hormona da tiroide usada para tratar o hipotiroidismo (tiroide pouco ativa). Substitui a hormona que o corpo não produz em quantidade suficiente. Toma-se diariamente em jejum, e a dose é ajustada com análises (TSH).',
   'Levothyroxine is the thyroid hormone used to treat hypothyroidism (underactive thyroid). It replaces the hormone the body does not produce in sufficient amounts. It is taken daily on an empty stomach, and the dose is adjusted with blood tests (TSH).',
   'Levotiroxina sódica (T4). Terapêutica de substituição no hipotiroidismo (primário, secundário, terciário) e supressão do TSH como adjuvante no carcinoma da tiroide bem diferenciado. Índice terapêutico estreito; sobretratamento causa hipertiroidismo iatrogénico (risco cardíaco no idoso); contraindicada na insuficiência suprarrenal não corrigida.',
   'Levothyroxine sodium (T4). Replacement therapy in hypothyroidism (primary, secondary, tertiary) and TSH suppression as adjunct in well-differentiated thyroid cancer. Narrow therapeutic index; overtreatment causes iatrogenic hyperthyroidism (cardiac risk in the elderly); contraindicated in uncorrected adrenal insufficiency.',
   E'Terapêutica de substituição no hipotiroidismo congénito ou adquirido (primário, secundário ou terciário), em adultos e crianças, incluindo recém-nascidos.\nSupressão do TSH (adjuvante de cirurgia e radioiodo) no carcinoma da tiroide bem diferenciado dependente de TSH.',
   E'Replacement therapy in congenital or acquired hypothyroidism (primary, secondary or tertiary), in adults and children, including neonates.\nTSH suppression (adjunct to surgery and radioiodine) in TSH-dependent, well-differentiated thyroid cancer.',
   E'Em dose correta é geralmente bem tolerada.\nSinais de dose excessiva (hipertiroidismo): palpitações, batimento rápido, nervosismo, ansiedade, insónia.\nPerda de peso, aumento do apetite, intolerância ao calor, sudação.\nTremores, fraqueza ou cãibras musculares.\nDiarreia, vómitos ou cólicas abdominais.\nQueda de cabelo ou alterações menstruais.',
   E'Well tolerated at the correct dose.\nSigns of excessive dose (hyperthyroidism): palpitations, fast heartbeat, nervousness, anxiety, insomnia.\nWeight loss, increased appetite, heat intolerance, sweating.\nTremors, muscle weakness or cramps.\nDiarrhoea, vomiting or abdominal cramps.\nHair loss or menstrual changes.',
   E'Tomar em jejum (30–60 minutos antes do pequeno-almoço) e sempre da mesma forma.\nSeparar 4 horas de medicamentos que interferem com a absorção (cálcio, ferro, antiácidos, inibidores da bomba de protões).\nNão suspender nem alterar a dose por conta própria — o ajuste é feito com análises (TSH).\nNo idoso ou com doença cardíaca, o início é com doses baixas (risco de angina/arritmias).\nContraindicada na insuficiência suprarrenal não corrigida (risco de crise suprarrenal).',
   E'Take on an empty stomach (30–60 minutes before breakfast) and always the same way.\nSeparate by 4 hours from medicines that interfere with absorption (calcium, iron, antacids, proton pump inhibitors).\nDo not stop or change the dose on your own — adjustment is guided by blood tests (TSH).\nIn the elderly or with heart disease, start at low doses (risk of angina/arrhythmias).\nContraindicated in uncorrected adrenal insufficiency (risk of adrenal crisis).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Levotiroxina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4ddcaec1-a58f-340b-9bc1-bbe048b8c885 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Levothyroxine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4ddcaec1-a58f-340b-9bc1-bbe048b8c885 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('atorvastatina',
   'A atorvastatina é uma estatina usada para baixar o colesterol "mau" (LDL) e reduzir o risco de enfarte e de acidente vascular cerebral (AVC). É geralmente bem tolerada; o principal efeito a vigiar é a dor muscular inexplicada.',
   'Atorvastatin is a statin used to lower "bad" cholesterol (LDL) and reduce the risk of heart attack and stroke. It is generally well tolerated; the main effect to watch for is unexplained muscle pain.',
   'Estatina (inibidor da HMG-CoA redutase). Reduz o LDL-C e a morbilidade/mortalidade cardiovascular (enfarte, AVC, revascularização) em doentes com múltiplos fatores de risco ou doença aterosclerótica estabelecida; também hiperlipidemia primária, hipertrigliceridemia e disbetalipoproteinemia. Risco de miopatia/rabdomiólise (aumentado por inibidores do CYP3A4/OATP1B1, doses altas, idade ≥65, hipotiroidismo, insuficiência renal).',
   'Statin (HMG-CoA reductase inhibitor). Reduces LDL-C and cardiovascular morbidity/mortality (heart attack, stroke, revascularisation) in patients with multiple risk factors or established atherosclerotic disease; also primary hyperlipidaemia, hypertriglyceridaemia and dysbetalipoproteinaemia. Risk of myopathy/rhabdomyolysis (increased by CYP3A4/OATP1B1 inhibitors, high doses, age ≥65, hypothyroidism, renal impairment).',
   E'Redução do risco de enfarte do miocárdio, AVC, revascularização e angina em adultos com múltiplos fatores de risco para doença coronária (sem doença evidente).\nRedução do risco de enfarte e AVC em adultos com diabetes tipo 2 e múltiplos fatores de risco.\nRedução do risco de eventos cardiovasculares em adultos com doença coronária evidente.\nRedução do LDL-C (adjuvante de dieta) na hiperlipidemia primária, hipercolesterolemia familiar heterozigótica (≥10 anos) e homozigótica, disbetalipoproteinemia e hipertrigliceridemia.',
   E'Reduction of the risk of myocardial infarction, stroke, revascularisation and angina in adults with multiple risk factors for coronary disease (without evident disease).\nReduction of the risk of heart attack and stroke in adults with type 2 diabetes and multiple risk factors.\nReduction of the risk of cardiovascular events in adults with evident coronary disease.\nReduction of LDL-C (adjunct to diet) in primary hyperlipidaemia, heterozygous (≥10 years) and homozygous familial hypercholesterolaemia, dysbetalipoproteinaemia and hypertriglyceridaemia.',
   E'Dor, sensibilidade ou fraqueza muscular — avisar o médico (risco de miopatia/rabdomiólise, sobretudo com febre ou mal-estar).\nDiarreia, náuseas, desconforto abdominal ou azia.\nDor nas articulações.\nDor de cabeça ou insónia.\nAlterações das provas de função hepática (raras).\nAumento ligeiro do açúcar no sangue (HbA1c).',
   E'Muscle pain, tenderness or weakness — tell your doctor (risk of myopathy/rhabdomyolysis, especially with fever or malaise).\nDiarrhoea, nausea, abdominal discomfort or heartburn.\nJoint pain.\nHeadache or insomnia.\nAbnormal liver function tests (rare).\nSlight increase in blood sugar (HbA1c).',
   E'Informar o médico de qualquer dor, sensibilidade ou fraqueza muscular inexplicada (sobretudo com mal-estar ou febre).\nEvitar sumo de toranja em grandes quantidades (>1,2 litros/dia).\nAnálises de função hepática e CK conforme orientação médica.\nAvisar o médico de outros medicamentos (inibidores do CYP3A4: certos antivirais, azóis, macrólidos — ex.: claritromicina, itraconazol — e gemfibrozil, ciclosporina).\nContraindicada em insuficiência hepática aguda ou cirrose descompensada.',
   E'Tell your doctor about any unexplained muscle pain, tenderness or weakness (especially with malaise or fever).\nAvoid grapefruit juice in large amounts (>1.2 litres per day).\nLiver function and CK tests as directed by your doctor.\nTell your doctor about other medicines (CYP3A4 inhibitors: certain antivirals, azoles, macrolides — e.g. clarithromycin, itraconazole — and gemfibrozil, ciclosporin).\nContraindicated in acute liver failure or decompensated cirrhosis.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Atorvastatina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=51e24220-3374-4e5e-9a8d-4113002c5bed — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Atorvastatin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=51e24220-3374-4e5e-9a8d-4113002c5bed — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('amlodipina',
   'A amlodipina é um medicamento para a tensão arterial alta e para a angina (dor no peito). Relaxa e alarga os vasos sanguíneos, facilitando a passagem do sangue. O efeito secundário mais comum é o inchaço dos tornozelos.',
   'Amlodipine is a medicine for high blood pressure and for angina (chest pain). It relaxes and widens the blood vessels, making it easier for blood to flow. The most common side effect is swelling of the ankles.',
   'Bloqueador dos canais de cálcio di-hidropiridínico. Indicado na hipertensão (isolado ou em associação) e na angina estável, angina vasoespástica (Prinzmetal) e doença coronária documentada. Edema periférico dose-dependente; titular lentamente na insuficiência hepática grave (meia-vida 56 horas).',
   'Dihydropyridine calcium channel blocker. Indicated in hypertension (alone or in combination) and in stable angina, vasospastic (Prinzmetal) angina and documented coronary artery disease. Dose-dependent peripheral oedema; titrate slowly in severe hepatic impairment (half-life 56 hours).',
   E'Hipertensão arterial (isolado ou em associação com outros anti-hipertensores) — reduz o risco de eventos cardiovasculares, principalmente AVC e enfarte.\nAngina estável crónica (tratamento sintomático).\nAngina vasoespástica (Prinzmetal ou variante).\nDoença coronária documentada por angiografia.',
   E'Hypertension (alone or in combination with other antihypertensives) — reduces the risk of cardiovascular events, mainly stroke and heart attack.\nChronic stable angina (symptomatic treatment).\nVasospastic (Prinzmetal or variant) angina.\nCoronary artery disease documented by angiography.',
   E'Inchaço dos tornozelos ou pés (edema — comum, relacionado com a dose).\nTonturas ou rubor (flush).\nPalpitações ou batimento rápido.\nFadiga, náuseas, dor abdominal ou sonolência.\nMenos frequentes: crescimento das gengivas (hiperplasia gengival) ou aumento de peso.',
   E'Swelling of the ankles or feet (oedema — common, dose-related).\nDizziness or flushing.\nPalpitations or fast heartbeat.\nFatigue, nausea, abdominal pain or drowsiness.\nLess common: gum overgrowth (gingival hyperplasia) or weight gain.',
   E'Tonturas ou pressão baixa ao levantar (hipotensão), sobretudo no início ou com doses maiores — informar o médico.\nEm doentes com doença coronária grave, avisar o médico se a dor no peito piorar ao iniciar ou aumentar a dose.\nInsuficiência hepática grave: ajuste lento da dose (meia-vida prolongada).\nNão usar em caso de alergia à amlodipina.',
   E'Dizziness or low blood pressure on standing (hypotension), especially at the start or with higher doses — tell your doctor.\nIn patients with severe coronary disease, tell the doctor if chest pain worsens when starting or increasing the dose.\nSevere hepatic impairment: slow dose adjustment (prolonged half-life).\nDo not use if allergic to amlodipine.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Amlodipina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=edf9b22c-e37e-4b4e-8a64-20bb036c7d2d — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Amlodipine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=edf9b22c-e37e-4b4e-8a64-20bb036c7d2d — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('omeprazol',
   'O omeprazol é um medicamento que reduz a produção de ácido no estômago (inibidor da bomba de protões). Usa-se para a azia frequente e, com receita médica, em problemas como refluxo, úlceras do estômago e do duodeno. Na azia frequente (2 ou mais dias por semana), pode demorar 1 a 4 dias a fazer efeito completo.',
   'Omeprazole is a medicine that reduces the production of acid in the stomach (proton pump inhibitor). It is used for frequent heartburn and, on prescription, for problems such as reflux and stomach and duodenal ulcers. For frequent heartburn (2 or more days a week), it may take 1 to 4 days for full effect.',
   'Inibidor da bomba de protões (H+/K+-ATPase). Sem receita: tratamento de curta duração da azia frequente. Com prescrição: úlcera péptica, esofagite de refluxo, síndrome de Zollinger-Ellison e erradicação do H. pylori (em associação). Inibidor do CYP2C19 (interação com clopidogrel; aumenta níveis de varfarina, fenitoína e diazepam).',
   'Proton pump inhibitor (H+/K+-ATPase). Over the counter: short-term treatment of frequent heartburn. On prescription: peptic ulcer, reflux oesophagitis, Zollinger-Ellison syndrome and H. pylori eradication (in combination). CYP2C19 inhibitor (interaction with clopidogrel; raises levels of warfarin, phenytoin and diazepam).',
   E'(Sem receita) Tratamento da azia frequente (2 ou mais dias por semana). Não é para alívio imediato — pode demorar 1 a 4 dias a fazer efeito completo.\n(Com receita médica — Prontuário Terapêutico) Úlcera péptica, esofagite de refluxo, síndrome de Zollinger-Ellison; erradicação do H. pylori em associação.',
   E'(Over the counter) Treatment of frequent heartburn (2 or more days a week). Not for immediate relief — may take 1 to 4 days for full effect.\n(On prescription — Prontuário Terapêutico) Peptic ulcer, reflux oesophagitis, Zollinger-Ellison syndrome; H. pylori eradication in combination.',
   E'Diarreia, dor abdominal, náuseas ou gases.\nDor de cabeça.\nErupção cutânea ou dor nas articulações — parar e falar com o médico.\nSinais de alergia grave (raros): vermelhidão da pele, bolhas, inchaço — procurar ajuda imediata.\nUso prolongado sem vigilância: défice de vitamina B12, fraturas ósseas, problemas renais — avaliação médica.',
   E'Diarrhoea, abdominal pain, nausea or gas.\nHeadache.\nSkin rash or joint pain — stop and talk to your doctor.\nSigns of severe allergy (rare): skin redness, blisters, swelling — seek immediate help.\nProlonged unsupervised use: vitamin B12 deficiency, bone fractures, kidney problems — medical evaluation.',
   E'Sem receita: 1 comprimido por dia, em jejum, durante 14 dias no máximo; repetir apenas a cada 4 meses.\nNão usar se tiver dor ou dificuldade ao engolir, vómitos com sangue, fezes escuras, dor no peito ou azia com tonturas/sudação — procurar médico (podem ser sinais de doença grave).\nSe a azia persistir mais de 3 meses ou com pieira frequente, falar com o médico.\nInformar o médico de outros medicamentos (ex.: clopidogrel, varfarina, fenitoína).',
   E'Over the counter: 1 tablet per day, on an empty stomach, for a maximum of 14 days; repeat only every 4 months.\nDo not use if you have pain or trouble swallowing, vomiting blood, dark stools, chest pain, or heartburn with dizziness/sweating — see a doctor (may be signs of serious disease).\nIf heartburn persists for more than 3 months or with frequent wheezing, talk to your doctor.\nTell your doctor about other medicines (e.g. clopidogrel, warfarin, phenytoin).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Omeprazol (OTC): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5baf6e08-8a5a-4ec0-af6d-eb73c6487e0c — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Omeprazole (OTC) label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5baf6e08-8a5a-4ec0-af6d-eb73c6487e0c — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)')
) AS v(slug, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
       indications_pt, indications_en, side_effects_pt, side_effects_en,
       precautions_pt, precautions_en, source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;

-- ---------------------------------------------------------------------
-- 2. UPDATE furosemida — completa com indicações/efeitos/precauções
--    (perfil criado na 079, sem estes campos até agora)
-- ---------------------------------------------------------------------
UPDATE public.drug_profiles
SET
  indications_pt = E'Tratamento do edema associado a insuficiência cardíaca, doença hepática ou doença renal (incluindo síndrome nefrótica).\nTratamento da hipertensão arterial (isolado ou em associação com outros anti-hipertensores).',
  indications_en = E'Treatment of oedema associated with heart failure, liver disease or kidney disease (including nephrotic syndrome).\nTreatment of hypertension (alone or in combination with other antihypertensives).',
  side_effects_pt = E'Aumento da frequência urinária.\nTonturas, sobretudo ao levantar (hipotensão ortostática), e desidratação.\nPotássio baixo (hipocaliemia): fraqueza, cãibras, sobretudo nas pernas.\nNáuseas, desconforto abdominal, diarreia ou obstipação.\nZumbidos ou perda de audição (raros, com doses elevadas ou injeção rápida).\nErupção cutânea ou fotossensibilidade.',
  side_effects_en = E'Increased frequency of urination.\nDizziness, especially on standing (orthostatic hypotension), and dehydration.\nLow potassium (hypokalaemia): weakness, cramps, especially in the legs.\nNausea, abdominal discomfort, diarrhoea or constipation.\nTinnitus or hearing loss (rare, with high doses or rapid injection).\nSkin rash or photosensitivity.',
  precautions_pt = E'Análises regulares (potássio, sódio, magnésio, função renal, ácido úrico, glucose).\nVigiar sinais de desidratação e de potássio baixo (fraqueza, cãibras, tonturas).\nEvitar álcool em excesso.\nCom fármacos ototóxicos (aminoglicosídeos, cisplatina) ou outros diuréticos — orientação médica.\nNão usar se não urinar (anúria) ou se tiver alergia à furosemida.\nCom AINE, lítio, digoxina ou sotalol — vigilância acrescida (interações).',
  precautions_en = E'Regular blood tests (potassium, sodium, magnesium, kidney function, uric acid, glucose).\nWatch for signs of dehydration and low potassium (weakness, cramps, dizziness).\nAvoid excess alcohol.\nWith ototoxic drugs (aminoglycosides, cisplatin) or other diuretics — medical guidance.\nDo not use if you are not urinating (anuria) or are allergic to furosemide.\nWith NSAIDs, lithium, digoxin or sotalol — increased surveillance (interactions).',
  source_pt = 'DailyMed/FDA (NIH/NLM) — rótulo aprovado Furosemida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=eac958dd-8d43-e44e-e053-2995a90a4d5e — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
  source_en = 'DailyMed/FDA (NIH/NLM) — approved Furosemide label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=eac958dd-8d43-e44e-e053-2995a90a4d5e — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)',
  updated_at = now()
FROM public.drugs d
WHERE d.id = drug_profiles.drug_id AND d.slug = 'furosemida';
